import {queueSummary,estimateOrders} from './domain.mjs';
import {menuDishPhoto,hasGeneratedMenuPhoto} from './photo-view.mjs';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const tr=(lang,en,th)=>lang==='th'?th:en;
export const money=(cents,lang='en')=>new Intl.NumberFormat(lang==='th'?'th-TH':'en-TH',{style:'currency',currency:'THB',maximumFractionDigits:cents%100?2:0}).format(cents/100);
export const itemName=(m,l)=>l==='th'&&m.nameTh?m.nameTh:m.name;
export const statusName=(s,l)=>tr(l,({queued:'New',preparing:'Preparing',ready:'Ready',served:'Served',cancelled:'Cancelled'})[s]||s,({queued:'ออเดอร์ใหม่',preparing:'กำลังทำ',ready:'พร้อมเสิร์ฟ',served:'เสิร์ฟแล้ว',cancelled:'ยกเลิก'})[s]||s);
const channel=(s,l)=>s==='online'?tr(l,'Online','ออนไลน์'):tr(l,'In-store','หน้าร้าน');
const num=n=>String(n).padStart(2,'0');
const pill=(text,extra='')=>`<span class="cp-pill ${extra}">${esc(text)}</span>`;
const methods={cash:['Cash','เงินสด'],promptpay:['PromptPay','พร้อมเพย์'],card:['Card','บัตร'],'government-assistance':['Government scheme — ask merchant','โครงการรัฐ — สอบถามร้าน']};
export function paymentNames(values,l){return (values||[]).map(id=>tr(l,...(methods[id]||[id,id]))).join(' · ');}
export function header({language:l,demo,guest,view}){return `<a class="cp-brand" href="/copilot${demo?'/demo':''}" aria-label="Soi Studio"><span>Soi</span><small>MERCHANT COPILOT</small></a>${guest?`<span class="cp-header-context">${tr(l,'Order at your table','สั่งอาหารที่โต๊ะ')}</span>`:`<nav class="cp-nav" aria-label="${tr(l,'Workspace','พื้นที่ทำงาน')}">${[['intelligence','Intelligence','ต้นทุน'],['order','Order menu','สั่งอาหาร'],['ai','AI demo','เดโม AI'],['service','Service','หน้าร้าน'],['menu','Menu setup','ตั้งค่าเมนู'],['settings','Membership','สมาชิก']].map(([key,en,th])=>`<a href="#${key}" ${view===key?'aria-current="page"':''}>${tr(l,en,th)}</a>`).join('')}</nav>`}<div class="cp-tools">${pill(demo?tr(l,'Simulated demo','เดโมจำลอง'):tr(l,'Full app','แอปเต็ม'))}<label><span class="sr-only">Language / ภาษา</span><select id="cp-language" aria-label="Language / ภาษา"><option value="en"${l==='en'?' selected':''}>EN</option><option value="th"${l==='th'?' selected':''}>ไทย</option></select></label>${!guest?`<a class="cp-link" href="${demo?'/demo':'/'}#overview">${tr(l,'Business studio','วิเคราะห์ธุรกิจ')} ↗</a>`:''}</div>`;}
export function footer({language:l,demo,guest}){return `<span>Soi Studio <span aria-hidden="true">/</span> ${tr(l,'Merchant copilot','ผู้ช่วยร้านค้า')}</span><span>${tr(l,'Orders here. Payment with your merchant.','สั่งอาหารที่นี่ ชำระเงินกับร้านค้า')}</span>${!guest?`<a href="/copilot${demo?'':'/demo'}">${demo?tr(l,'Open full app','เปิดแอปเต็ม'):tr(l,'Explore demo','ทดลองเดโม')} ↗</a>`:''}`;}
export function serviceView({state,language:l,demo,filter}){const s=queueSummary(state),now=new Date();return `<div class="cp-shell cp-view"><section class="cp-hero"><div class="cp-hero-copy" data-reveal><p class="cp-eyebrow">${esc(state.settings.name)} <span aria-hidden="true">/</span> ${now.toLocaleDateString(l==='th'?'th-TH':'en-GB',{day:'numeric',month:'short'})}</p><h1>${tr(l,'Service,<br>in sync.','ทุกรายการ<br>เข้าจังหวะ')}</h1><p class="cp-subtitle">${tr(l,'One kitchen. In-store and online, beautifully in order.','ครัวเดียว ดูออเดอร์หน้าร้านและออนไลน์ได้พร้อมกัน')}</p><div class="cp-hero-actions"><button class="cp-button" data-action="new-order">${tr(l,'Add an order','เพิ่มออเดอร์')} <span aria-hidden="true">+</span></button><a class="cp-button secondary" href="#order">${tr(l,'Open table menu','เปิดเมนูโต๊ะ')} ↗</a></div><p class="cp-note">${demo?tr(l,'Sample service · all orders are simulated.','ตัวอย่างหน้าร้าน · ทุกออเดอร์เป็นข้อมูลจำลอง'):tr(l,'Private queue · online orders entered manually.','คิวส่วนตัว · เพิ่มออเดอร์ออนไลน์ด้วยตนเอง')}</p></div><div class="cp-scene" data-reveal><button class="cp-window" data-scene-light aria-pressed="false" aria-label="${tr(l,'Change the mountain light','เปลี่ยนแสงวิวภูเขา')}"><span class="cp-camera"><img class="cp-landscape" src="/images/studio-window.webp" alt="" width="1200" height="800" fetchpriority="high"><span class="cp-reflection"></span><span class="cp-light"></span></span></button><div class="cp-float-ticket" aria-hidden="true"><span class="cp-eyebrow">${tr(l,'THE KITCHEN','ในครัว')}</span><strong data-hero-count>${num(s.activeOrders)}</strong><span>${tr(l,'orders in rhythm','ออเดอร์ในคิว')}</span><span class="cp-ticket-stroke"></span><small>${tr(l,'In-store','หน้าร้าน')} <b data-hero-offline>${s.offlineOrders}</b> <span aria-hidden="true">/</span> ${tr(l,'Online','ออนไลน์')} <b data-hero-online>${s.onlineOrders}</b></small></div><span class="cp-scene-caption">${tr(l,'A little room to breathe.','พื้นที่ให้ร้านหายใจ')}</span></div></section><section id="cp-service" data-reveal><div class="cp-service-title"><div><p class="cp-eyebrow">${tr(l,'YOUR SERVICE','หน้าร้านของคุณ')}</p><h2>${tr(l,'The pass.','หน้าครัว')}</h2></div><div class="cp-filters" aria-label="${tr(l,'Filter orders','กรองออเดอร์')}">${[['all','All orders','ทั้งหมด'],['offline','In-store','หน้าร้าน'],['online','Online','ออนไลน์']].map(([id,en,th])=>`<button data-filter="${id}" aria-pressed="${filter===id}">${tr(l,en,th)}</button>`).join('')}<button class="cp-button quiet" data-action="refresh">${tr(l,'Refresh','รีเฟรช')}</button></div></div><div id="cp-queue">${queueView({state,language:l,filter})}</div></section><section class="cp-bottom-bridge" data-reveal><p class="cp-eyebrow">${tr(l,'BEYOND THE QUEUE','มากกว่าการจัดคิว')}</p><h2>${tr(l,'Know what comes next.','เห็นทางเลือกต่อไป')}</h2><div class="cp-hero-actions"><a class="cp-button secondary" href="${demo?'/demo':'/'}#advisor">${tr(l,'Ask your business copilot','คุยกับผู้ช่วยธุรกิจ')} ↗</a><a class="cp-link" href="${demo?'/demo':'/'}#workflow">${tr(l,'Explore profit & scenarios','ดูกำไรและจำลองแผน')} →</a></div><p class="cp-note">${tr(l,'Service orders stay separate from confirmed financial reports.','ออเดอร์หน้าร้านแยกจากรายงานการเงินที่ยืนยันแล้ว')}</p></section></div>`;}
export function queueView({state,language:l,filter='all'}){const s=queueSummary(state),etas=estimateOrders(state),orders=state.orders.filter(o=>filter==='all'||o.channel===filter);return `<div class="cp-summary">${[[num(s.activeOrders),'Active orders','ออเดอร์ที่ยังไม่เสร็จ'],[num(s.readyOrders),'Ready to serve','พร้อมเสิร์ฟ'],[`${s.estimatedMinutes} ${tr(l,'min','นาที')}`,'Estimated queue clearance','ประมาณเวลาจบคิว']].map(([value,en,th])=>`<div class="cp-stat"><small>${tr(l,en,th)}</small><strong>${value}</strong></div>`).join('')}</div><div class="cp-queue-layout"><div class="cp-board">${['queued','preparing','ready'].map(status=>`<section class="cp-lane"><h3>${statusName(status,l)} <span>${orders.filter(o=>o.status===status).length}</span></h3>${orders.filter(o=>o.status===status).map(o=>orderTicket(o,l,etas[o.id])).join('')||`<div class="cp-empty">${tr(l,'A clear pass.','ยังไม่มีรายการ')}</div>`}</section>`).join('')}</div><aside class="cp-aggregate"><p class="cp-eyebrow">${tr(l,'COOK TOGETHER','เตรียมพร้อมกัน')}</p><h3>${tr(l,'Kitchen totals','ยอดรวมในครัว')}</h3><p class="cp-note">${tr(l,'All channels · awaiting preparation','ทุกช่องทาง · รายการที่ยังเตรียมไม่เสร็จ')}</p>${s.items.map(item=>`<div class="cp-aggregate-row"><div><strong>${esc(itemName(item,l))}</strong>${item.note?`<small>${esc(item.note)}</small>`:''}<small>${tr(l,'Store','หน้าร้าน')} ${item.offline} <span aria-hidden="true">/</span> ${tr(l,'Online','ออนไลน์')} ${item.online}</small></div><b>${item.quantity}</b></div>`).join('')||`<p>${tr(l,'Everything is ready.','ทุกอย่างพร้อมแล้ว')}</p>`}<p class="cp-note">${tr(l,'Estimates use item prep times, backlog and parallel capacity. Merchant confirmation comes first.','เวลาโดยประมาณคำนวณจากเวลาเตรียม คิว และกำลังการผลิต โปรดยืนยันกับร้าน')}</p></aside></div>${orders.some(o=>['served','cancelled'].includes(o.status))?`<details class="cp-history"><summary>${tr(l,'Completed & cancelled','เสร็จสิ้นและยกเลิก')}</summary>${orders.filter(o=>['served','cancelled'].includes(o.status)).slice(-12).reverse().map(o=>`<div class="cp-history-row"><span>#${num(o.number)} · ${esc(o.table||channel(o.channel,l))}</span><span>${statusName(o.status,l)}</span><span>${money(o.totalCents,l)} <small>${tr(l,'order value','มูลค่าออเดอร์')}</small></span></div>`).join('')}</details>`:''}`;}
function orderTicket(o,l,eta){const next={queued:'preparing',preparing:'ready',ready:'served'},label={queued:tr(l,'Start cooking','เริ่มทำ'),preparing:tr(l,'Mark ready','พร้อมเสิร์ฟ'),ready:tr(l,'Handed over','ส่งมอบแล้ว')};return `<article class="cp-ticket"><header><strong class="cp-order-no">#${num(o.number)}</strong><span class="cp-channel ${o.channel}">${channel(o.channel,l)}</span></header><p class="cp-table">${esc(o.table||tr(l,'Counter','เคาน์เตอร์'))} ${o.source==='manual'?`<small>· ${tr(l,'manual','เพิ่มด้วยตนเอง')}</small>`:''}</p><ul class="cp-ticket-lines">${o.items.map(i=>`<li><span>${i.quantity} × ${esc(itemName(i,l))}${i.note?`<small>${esc(i.note)}</small>`:''}</span></li>`).join('')}</ul>${o.note?`<p class="cp-order-note">${esc(o.note)}</p>`:''}<div class="cp-ticket-foot"><span>${o.status==='ready'?tr(l,'Ready now','พร้อมแล้ว'):`~${eta} ${tr(l,'min','นาที')}`}</span><button class="cp-button secondary" data-status="${next[o.status]}" data-order="${o.id}">${label[o.status]}</button></div><button class="cp-link cp-cancel" data-cancel="${o.id}">${tr(l,'Cancel order','ยกเลิกออเดอร์')}</button></article>`;}
export function menuView({state,language:l,demo,table}){return `<div class="cp-shell cp-view"><div class="cp-page-head" data-reveal><p class="cp-eyebrow">${tr(l,'A SEAT AT YOUR TABLE','พร้อมสำหรับทุกโต๊ะ')}</p><h1>${tr(l,'Your menu.<br>Their moment.','เมนูของคุณ<br>ช่วงเวลาของลูกค้า')}</h1><p>${tr(l,'In-store prices for table orders. A separate price for online orders.','ใช้ราคาหน้าร้านสำหรับออเดอร์ที่โต๊ะ แยกราคาสำหรับออเดอร์ออนไลน์')}</p></div><div class="cp-menu-layout"><section class="cp-section" data-reveal><div class="cp-service-title"><h2>${tr(l,'The menu','รายการอาหาร')}</h2><a class="cp-link" href="#order">${tr(l,'Try the order menu','ลองเมนูสั่งอาหาร')} ↗</a><button class="cp-button secondary" data-action="edit-menu">${tr(l,'Edit menu','แก้ไขเมนู')}</button><button class="cp-button quiet" data-action="import-menu">${tr(l,'Import menu','นำเข้าเมนู')} ↗</button></div><div class="cp-menu-list"><div class="cp-menu-row cp-menu-head"><span>${tr(l,'Menu item','รายการ')}</span><span>${tr(l,'Store','หน้าร้าน')}</span><span>${tr(l,'Online','ออนไลน์')}</span><span>${tr(l,'Prep','เวลา')}</span></div>${state.menu.map(m=>`<div class="cp-menu-row"><div><strong>${esc(itemName(m,l))}</strong><small>${esc(tr(l,m.category,m.category==='Drinks'?'เครื่องดื่ม':m.category==='Kitchen'?'ครัว':m.category))} ${!m.available?' · '+tr(l,'Unavailable','ไม่พร้อมขาย'):''}</small></div><span data-label="${tr(l,'Store','หน้าร้าน')}">${money(m.storePriceCents,l)}</span><span data-label="${tr(l,'Online','ออนไลน์')}">${money(m.onlinePriceCents,l)}</span><span data-label="${tr(l,'Prep','เวลา')}">${m.prepMinutes} ${tr(l,'min','นาที')}</span></div>`).join('')}</div><p class="cp-note">${tr(l,'Illustrative menu until you edit it. Prices are entered by the merchant; Grab menu sync is not connected.','เมนูตัวอย่างจนกว่าจะแก้ไข ราคากำหนดโดยร้าน ยังไม่ได้เชื่อมเมนู Grab')}</p></section><aside class="cp-qr-panel" data-reveal><p class="cp-eyebrow">${tr(l,'SCAN. CHOOSE. SEND.','สแกน เลือก ส่งออเดอร์')}</p><h2>${tr(l,'A table, connected.','เชื่อมโต๊ะถึงครัว')}</h2><label class="cp-field">${tr(l,'Table label','ชื่อโต๊ะ')}<input id="cp-qr-table" value="${esc(table)}" maxlength="40" autocomplete="off"></label><div class="cp-qr-art"><canvas id="cp-qr" aria-label="${tr(l,'QR code for this table menu','QR โค้ดเมนูของโต๊ะนี้')}"></canvas></div><a class="cp-button" id="cp-menu-link" href="#">${tr(l,'Open customer view','เปิดมุมมองลูกค้า')} ↗</a><button class="cp-button quiet" data-action="copy-menu">${tr(l,'Copy menu link','คัดลอกลิงก์เมนู')}</button><p class="cp-note">${demo?tr(l,'Demo orders sync only in this browser. Another device gets its own sample.','เดโมซิงก์เฉพาะเบราว์เซอร์นี้ อุปกรณ์อื่นใช้ข้อมูลตัวอย่างของตัวเอง'):tr(l,'This link shares your menu publicly. Switch on QR ordering in Membership after checking your prices.','ลิงก์นี้เปิดเผยเมนูต่อสาธารณะ ตรวจสอบราคาแล้วเปิดรับออเดอร์ QR ในหน้าสมาชิก')}</p>${pill(state.settings.accepting?tr(l,'QR ordering open','เปิดรับออเดอร์ QR'):tr(l,'QR ordering paused','พักรับออเดอร์ QR'))}</aside></div></div>`;}
export function settingsView({state,language:l,demo}){return `<div class="cp-shell cp-view"><div class="cp-page-head" data-reveal><p class="cp-eyebrow">${tr(l,'YOUR SHOP, YOUR WAY','ร้านของคุณ วิธีของคุณ')}</p><h1>${tr(l,'A quieter kind<br>of copilot.','ผู้ช่วยที่เข้าใจ<br>จังหวะร้าน')}</h1></div><div class="cp-settings-grid"><section class="cp-section" data-reveal><h2>${tr(l,'Service settings','ตั้งค่าหน้าร้าน')}</h2><form id="cp-settings-form" class="cp-form"><label class="cp-field">${tr(l,'Shop name','ชื่อร้าน')}<input name="name" value="${esc(state.settings.name)}" maxlength="100" required></label><label class="cp-field">${tr(l,'Parallel capacity per kitchen station','จำนวนรายการที่ทำพร้อมกันต่อสถานีครัว')}<input name="capacity" type="number" min="1" max="6" step="1" required value="${state.settings.capacity}"></label><label class="cp-field">${tr(l,'Grab menu link (optional)','ลิงก์เมนู Grab (ไม่บังคับ)')}<input name="grabMenuUrl" type="url" placeholder="https://food.grab.com/…" value="${esc(state.settings.grabMenuUrl)}" maxlength="400"></label><p class="cp-note">${tr(l,'Opens the merchant’s Grab page separately. No menu sync or price override on Grab.','เปิดหน้าร้านบน Grab แยกต่างหาก ไม่ซิงก์หรือเปลี่ยนราคาบน Grab')}</p><fieldset><legend>${tr(l,'Payment with your merchant','ช่องทางที่ร้านรับชำระ')}</legend>${Object.entries(methods).map(([id,label])=>`<label class="cp-check"><input name="paymentMethods" type="checkbox" value="${id}" ${state.settings.paymentMethods.includes(id)?'checked':''}> ${tr(l,...label)}</label>`).join('')}</fieldset><p class="cp-note">${tr(l,'Information only. Government assistance is subject to the merchant’s eligibility and the scheme’s rules. SOI does not process or verify payments.','แสดงข้อมูลเท่านั้น การใช้สิทธิ์รัฐขึ้นอยู่กับคุณสมบัติร้านและเงื่อนไขโครงการ SOI ไม่รับหรือตรวจสอบการชำระเงิน')}</p><label class="cp-check"><input name="accepting" type="checkbox" ${state.settings.accepting?'checked':''}>${tr(l,'Accept QR orders after reviewing my public menu and prices','เปิดรับออเดอร์ QR หลังตรวจสอบเมนูสาธารณะและราคาแล้ว')}</label><button class="cp-button" type="submit">${tr(l,'Save service settings','บันทึกการตั้งค่า')}</button></form></section><aside class="cp-plan" data-reveal><p class="cp-eyebrow">SOI MEMBERSHIP</p><h2>${tr(l,'A subscription.<br>A shared rhythm.','ระบบสมาชิก<br>เพื่อจังหวะร้านที่ดีขึ้น')}</h2><p>${tr(l,'Monthly access for your merchant copilot. Keep checkout with the tools and payment channels you already use.','ใช้ผู้ช่วยร้านค้าผ่านสมาชิกรายเดือน ชำระเงินผ่านเครื่องมือและช่องทางเดิมของร้าน')}</p><div class="cp-plan-price">${tr(l,'Pricing in development','กำลังออกแบบราคา')}</div><p class="cp-note">${tr(l,'Subscription model proposed. This preview has no billing or charges.','โมเดลสมาชิกรายเดือนที่เสนอ เดโมนี้ไม่มีระบบเรียกเก็บเงิน')}</p><a class="cp-link" href="${demo?'/demo':'/'}">${tr(l,'Analytics, advisor & business memory','การวิเคราะห์ ผู้ช่วย และความจำธุรกิจ')} ↗</a>${demo?`<button class="cp-button secondary" data-action="reset-demo">${tr(l,'Restart sample service','เริ่มเดโมใหม่')}</button>`:''}</aside></div></div>`;}
export function guestView({data,language:l,demo,category='all',cartCount=0,table}){const cats=[...new Set(data.menu.map(m=>m.category))],shown=data.menu.filter(m=>category==='all'||m.category===category);return `<div class="cp-guest-shell cp-view"><section class="cp-guest-hero"><img src="/images/studio-window.webp" alt="" width="1200" height="800"><div><p class="cp-eyebrow">${tr(l,'WELCOME TO','ยินดีต้อนรับสู่')}</p><h1>${esc(data.shop.name)}</h1><p>${esc(table)} · ${tr(l,'In-store prices','ราคาหน้าร้าน')}</p></div></section><div class="cp-guest-intro" data-reveal><h2>${tr(l,'Something lovely<br>for your table.','มื้อดี ๆ<br>สำหรับโต๊ะของคุณ')}</h2><p>${tr(l,'Choose your favourites. Send to the kitchen. Pay directly with the merchant.','เลือกเมนู ส่งให้ครัว แล้วชำระกับร้านค้าโดยตรง')}</p>${demo?pill(tr(l,'Simulated menu · no real order','เมนูจำลอง · ไม่ใช่ออเดอร์จริง')):''}${!data.shop.accepting?`<p class="cp-error" role="status">${tr(l,'QR orders are paused. Please order with the merchant.','พักรับออเดอร์ QR กรุณาสั่งกับร้านโดยตรง')}</p>`:''}</div><div class="cp-menu-categories" aria-label="${tr(l,'Menu categories','หมวดหมู่เมนู')}">${['all',...cats].map(c=>`<button data-category="${esc(c)}" aria-pressed="${category===c}">${esc(c==='all'?tr(l,'All','ทั้งหมด'):tr(l,c,c==='Drinks'?'เครื่องดื่ม':c==='Kitchen'?'อาหาร':c))}</button>`).join('')}</div>${data.menu.some(item=>hasGeneratedMenuPhoto(item,{demo}))?`<p class="cp-menu-photo-note">${tr(l,'AI-generated illustrations. Actual dishes may vary.','ภาพประกอบที่สร้างด้วย AI อาหารจริงอาจแตกต่าง')}</p>`:''}<div class="cp-dishes">${shown.map((m,i)=>`<article class="cp-dish" data-reveal>${menuDishPhoto(m,{language:l,demo,index:data.menu.indexOf(m)+1})}<div><h3>${esc(itemName(m,l))}</h3><p>${m.prepMinutes} ${tr(l,'min preparation · queue additional','นาทีในการเตรียม · ยังไม่รวมคิว')}</p><strong>${money(m.storePriceCents,l)}</strong></div><button class="cp-button secondary" data-add="${m.id}" aria-label="${esc(tr(l,'Add ','เพิ่ม ')+itemName(m,l))}" ${data.shop.accepting?'':'disabled'}>+</button></article>`).join('')}</div><div class="cp-guest-payment"><p>${tr(l,'Pay with your merchant','ชำระกับร้านโดยตรง')}</p><strong>${esc(paymentNames(data.shop.paymentMethods,l)||tr(l,'Ask your merchant','สอบถามร้าน'))}</strong><p class="cp-note">${tr(l,'Ask the merchant about eligibility before using a government payment scheme.','สอบถามร้านเรื่องสิทธิ์และเงื่อนไขก่อนใช้โครงการรัฐ')}</p>${data.shop.grabMenuUrl?`<a class="cp-link" href="${esc(data.shop.grabMenuUrl)}" target="_blank" rel="noopener noreferrer">${tr(l,'Visit this merchant on Grab','ดูร้านนี้บน Grab')} ↗</a>`:''}</div><div class="cp-cart-bar"><span><strong id="cp-cart-count">${cartCount}</strong> ${tr(l,'items selected','รายการที่เลือก')}</span><button class="cp-button" data-action="review-cart" ${cartCount?'':'disabled'}>${tr(l,'Review order','ตรวจสอบออเดอร์')} →</button></div></div>`;}
export function trackingView({order:o,language:l,demo}){return `<div class="cp-guest-shell cp-view"><section class="cp-tracking" data-reveal><p class="cp-eyebrow">${demo?tr(l,'SIMULATED ORDER','ออเดอร์จำลอง'):tr(l,'SENT TO THE KITCHEN','ส่งถึงครัวแล้ว')}</p><h1>${tr(l,'You’re in<br>good hands.','ครัวได้รับ<br>ออเดอร์แล้ว')}</h1><div class="cp-tracking-number">#${num(o.number)}</div><h2>${statusName(o.status,l)}</h2><p>${['queued','preparing'].includes(o.status)?`${tr(l,'Estimated ready in','คาดว่าพร้อมใน')} ~${o.etaMinutes} ${tr(l,'min','นาที')}`:tr(l,'Please check with your merchant.','กรุณาตรวจสอบกับร้าน')}</p><ol class="cp-status-steps">${['queued','preparing','ready','served'].map(s=>`<li${s===o.status?' aria-current="step"':''}>${statusName(s,l)}</li>`).join('')}</ol><div class="cp-tracking-items">${o.items.map(i=>`<div><span>${i.quantity} × ${esc(itemName(i,l))}${i.note?` · ${esc(i.note)}`:''}</span><span>${money(i.lineTotalCents,l)}</span></div>`).join('')}</div><div class="cp-cart-total"><span>${tr(l,'Order value','มูลค่าออเดอร์')}</span><strong>${money(o.totalCents,l)}</strong></div><p>${tr(l,'Payment is still arranged directly with your merchant.','ชำระเงินกับร้านค้าโดยตรง')}</p><p class="cp-note">${tr(l,'This is an order acknowledgement, not a payment receipt. Preparation time is an estimate.','นี่คือการรับทราบออเดอร์ ไม่ใช่ใบเสร็จชำระเงิน เวลาเตรียมเป็นการประมาณ')}</p><div class="cp-hero-actions"><button class="cp-button secondary" data-action="refresh-tracking">${tr(l,'Refresh status','รีเฟรชสถานะ')}</button><button class="cp-button quiet" data-action="back-menu">${tr(l,'Back to menu','กลับไปที่เมนู')}</button>${demo?`<a class="cp-link" href="/copilot/demo#service">${tr(l,'See merchant queue','ดูคิวฝั่งร้าน')} ↗</a>`:''}</div></section></div>`;}
export function errorView(error,l,demo=false){return `<div class="cp-shell cp-view cp-empty"><p class="cp-eyebrow">SOI STUDIO</p><h1>${tr(l,error.status===401?'Your merchant workspace.':'Let’s reconnect.',error.status===401?'พื้นที่ร้านค้าของคุณ':'เชื่อมต่ออีกครั้ง')}</h1><p class="cp-error">${esc(error.message)}</p><div class="cp-hero-actions">${error.signinPath?`<a class="cp-button" href="${esc(error.signinPath)}">${tr(l,'Sign in','เข้าสู่ระบบ')}</a>`:`<button class="cp-button" data-action="retry">${tr(l,'Try again','ลองอีกครั้ง')}</button>`}<a class="cp-button secondary" href="/copilot/demo">${tr(l,'Explore the full demo','ทดลองเดโมครบทุกขั้นตอน')}</a></div></div>`;}
